/// have some value. Even then, the documentation can be rewritten to match the
/// shorter code.
///
/// ### Example
/// ```no_run
/// # let x = true;
/// if x {
///     false
/// } else {
///     true
/// }
/// # ;
/// ```
///
/// Use instead:
/// ```no_run
/// # let x = true;
/// !x
/// # ;
/// ```
///
/// Or, for the early-return guard form:
/// ```
/// # fn f(c: bool) -> Result<bool, ()> {
/// if c {
///     return Ok(true);
/// }
/// Ok(false)
/// # }
/// ```
///
/// Use instead:
/// ```
/// # fn f(c: bool) -> Result<bool, ()> {
/// Ok(c)
/// # }
/// ```
